RIDES = [
    ('Fast & Furious - Supercharged', 'simulator dark ride'),
    ("Fievel's Playland", 'play area'),
]
print('Ride-type classifier for Universal Studios Florida: San Francisco')
counts = {}
for name, kind in RIDES:
    counts[kind] = counts.get(kind, 0) + 1
    print("%s -> %s" % (name, kind))
for kind in sorted(counts):
    print("%s: %d" % (kind, counts[kind]))
print("Total operating rides listed: %d" % len(RIDES))

